import { defineConfig } from 'vite'
import { existsSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { execFile } from 'node:child_process'
import react from '@vitejs/plugin-react'
import { cloudflare } from '@cloudflare/vite-plugin'

/* Extra pages served next to the homepage, each at `/<name>` from `<name>.html`. */
const PAGES = ['v1', 'v2-0-0']

/* Blog pages generated by scripts/sync-notion.mjs (blog.html, blog/*.html, en/blog.html,
   en/blog/*.html): built like the homepage so they get the same bundled CSS/JS. */
function blogPages() {
  const pages = {}
  for (const dir of ['', 'en/']) {
    if (existsSync(resolve(__dirname, `${dir}blog.html`))) pages[`${dir}blog`] = resolve(__dirname, `${dir}blog.html`)
    const sub = resolve(__dirname, `${dir}blog`)
    if (!existsSync(sub)) continue
    for (const f of readdirSync(sub)) if (f.endsWith('.html')) pages[`${dir}blog/${f.slice(0, -5)}`] = resolve(sub, f)
  }
  return pages
}

/* Dev-only: let `/<name>` resolve to `<name>.html` (Cloudflare assets do this in prod). */
function pageRewrite() {
  return {
    name: 'page-rewrite',
    configureServer(server) {
      server.middlewares.use((req, _res, next) => {
        const name = req.url?.replace(/^\/|\/$/g, '')
        if (PAGES.includes(name)) req.url = `/${name}.html`
        /* Generated blog pages (see blogPages). Real files (blog images in public/) are served as-is. */
        else if (/^(en\/)?blog(\/[^.]+)?$/.test(name ?? '')) req.url = `/${name}.html`
        next()
      })
    },
  }
}

/* Dev-only, with BLOG_MOCK=1 (`npm run dev:blog`): generate the blog from fake articles,
   then regenerate whenever a blog template or the fake articles change (Vite reloads the page on public/ changes). */
function blogMock() {
  return {
    name: 'blog-mock',
    apply: 'serve',
    configureServer(server) {
      if (!process.env.BLOG_MOCK) return
      const sync = () => new Promise((done) => {
        execFile('node', ['scripts/sync-notion.mjs'], { cwd: __dirname, env: process.env }, (err, stdout, stderr) => {
          if (err) server.config.logger.error(stderr || err.message)
          else server.config.logger.info(stdout.trim().split('\n').at(-1), { timestamp: true })
          done()
        })
      })
      const watched = [resolve(__dirname, 'scripts/blog'), resolve(__dirname, 'scripts/dev/mock-blog.mjs'), resolve(__dirname, 'v2/strings.js'), resolve(__dirname, 'translations.js')]
      server.watcher.add(watched)
      server.watcher.on('change', (file) => {
        if (watched.some((w) => file.startsWith(w))) sync()
      })
      return sync()
    },
  }
}

/* Put the cookie consent script right after `<head>` in every page Vite serves or builds (homepage,
   extra pages, blog). It alone loads Google Analytics, and only after consent; see public/consent.js.
   public/404.html isn't built by Vite and carries the same tag itself. */
function consent() {
  return {
    name: 'consent',
    transformIndexHtml: (html) => html.replace(/<head[^>]*>/i, (head) => `${head}\n<script src="/consent.js"></script>`),
  }
}

export default defineConfig({
  plugins: [pageRewrite(), blogMock(), consent(), react(), cloudflare()],
  build: {
    rollupOptions: {
      input: {
        main: resolve(__dirname, 'index.html'),
        ...Object.fromEntries(PAGES.map((name) => [name, resolve(__dirname, `${name}.html`)])),
        ...blogPages(),
      },
    },
  },
})
